import React from 'react';

const thresholds = [
  { label: 'Pre-Event Recording',  value: '10 Minutes' },
  { label: 'Post-Event Recording', value: '10 Minutes' },
  { label: 'Segment Duration',     value: '10 Minutes' },
  { label: 'Confidence Threshold', value: '0.50' },
];

export default function ThresholdPanel() {
  return (
    <div style={{ borderBottom: '1px solid #1e2d47', padding: '10px 12px', flexShrink: 0 }}>
      <div style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px', marginBottom: 8 }}>
        Recording & Thresholds
      </div>
      {thresholds.map((t, i) => (
        <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '5px 0', borderBottom: '1px solid #1e2d47' }}>
          <span style={{ fontSize: 11, color: '#94a3b8' }}>{t.label}</span>
          <span style={{ fontSize: 11, fontWeight: 600, color: '#fff', display: 'flex', alignItems: 'center', gap: 5 }}>
            {t.value} <span style={{ fontSize: 12, color: '#64748b', cursor: 'pointer' }}>✏️</span>
          </span>
        </div>
      ))}
      <button style={{
        background: '#3b82f6', color: '#fff', border: 'none',
        width: '100%', padding: '7px', borderRadius: 6,
        fontSize: 11, fontWeight: 700, cursor: 'pointer', marginTop: 8
      }}>
        Save Settings
      </button>
    </div>
  );
}
